1	import { SUBPAGE_STARFIELD } from "../config/component.config.js";
2	import { FrameScheduler } from "../utils/FrameScheduler.js";
3	import { ResponsiveRuntime } from "./ResponsiveRuntime.js";
4	import type { SubpageStarfieldStar } from "../types/component.types.js";
5	
6	export class SubpageStarfieldRuntime {
7	  private _canvas: HTMLCanvasElement | null = null;
8	  private _context: CanvasRenderingContext2D | null = null;
9	  private _stars: SubpageStarfieldStar[] = [];
10	  private _width = 0;
11	  private _height = 0;
12	  private _centerX = 0;
13	  private _centerY = 0;
14	  private _rafId: number | null = null;
15	  private _pageshowListenerAttached = false;
16	  private _scrollListener: (() => void) | null = null;
17	  private _unsubscribeResponsive: (() => void) | null = null;
18	  private _resizeDirty = false;
19	  private _cachedViewportHeight = 1;
20	  private _cachedReducedMotion = false;
21	  private _scrollBoost = 0;
22	  private _targetScrollBoost = 0;
23	  private _lastScrollY = 0;
24	  private _lastFrameTime = 0;
25	
26	  init(root?: ParentNode | null): void {
27	    this.dispose();
28	    if (!this._isEligible()) return;
29	    const scope = root ?? document;
30	    const canvas = scope.querySelector<HTMLCanvasElement>(
31	      SUBPAGE_STARFIELD.canvasSelector,
32	    );
33	    if (!canvas) return;
34	    const context = canvas.getContext("2d");
35	    if (!context) return;
36	    this._canvas = canvas;
37	    this._context = context;
38	    this._lastScrollY = window.scrollY ?? window.pageYOffset ?? 0;
39	    this._bindEvents();
40	    this._resize();
41	    this._seedStars();
42	    this._lastFrameTime = performance.now();
43	    this._startLoop();
44	    if (!this._pageshowListenerAttached) {
45	      window.addEventListener("pageshow", this._pageshowHandler);
46	      this._pageshowListenerAttached = true;
47	    }
48	  }
49	
50	  dispose(): void {
51	    if (this._rafId !== null) {
52	      FrameScheduler.cancel(this._rafId);
53	      this._rafId = null;
54	    }
55	    if (this._pageshowListenerAttached) {
56	      window.removeEventListener("pageshow", this._pageshowHandler);
57	      this._pageshowListenerAttached = false;
58	    }
59	    if (this._unsubscribeResponsive) {
60	      this._unsubscribeResponsive();
61	      this._unsubscribeResponsive = null;
62	    }
63	    if (this._scrollListener) {
64	      window.removeEventListener("scroll", this._scrollListener);
65	      this._scrollListener = null;
66	    }
67	    this._canvas = null;
68	    this._context = null;
69	    this._stars = [];
70	    this._width = 0;
71	    this._height = 0;
72	    this._centerX = 0;
73	    this._centerY = 0;
74	    this._scrollBoost = 0;
75	    this._targetScrollBoost = 0;
76	    this._lastScrollY = 0;
77	    this._lastFrameTime = 0;
78	    this._resizeDirty = false;
79	    this._cachedViewportHeight = 1;
80	  }
81	
82	  private _isEligible(): boolean {
83	    const pathname = window.location.pathname || "/";
84	    return SUBPAGE_STARFIELD.pagePrefixes.some((prefix) =>
85	      pathname.startsWith(prefix),
86	    );
87	  }
88	
89	  private readonly _pageshowHandler = (e: PageTransitionEvent): void => {
90	    if (!e.persisted) return;
91	    if (!this._canvas) return;
92	    // bfcache 복원: RAF 체인 끊김 → 취소 후 재시작
93	    if (this._rafId !== null) {
94	      FrameScheduler.cancel(this._rafId);
95	      this._rafId = null;
96	    }
97	    this._lastFrameTime = performance.now();
98	    this._startLoop();
99	  };
100	
101	  private _bindEvents(): void {
102	    const responsive = ResponsiveRuntime.getDefault();
103	    const refreshCache = (): void => {
104	      const snapshot = responsive.getSnapshot();
105	      this._cachedViewportHeight = Math.max(1, snapshot.viewportHeight || 0);
106	      this._cachedReducedMotion = snapshot.flags.reducedMotion;
107	    };
108	    refreshCache();
109	    this._unsubscribeResponsive = responsive.subscribe(() => {
110	      this._resizeDirty = true;
111	      refreshCache();
112	    });
113	    this._scrollListener = () => this._syncScrollBoost();
114	    window.addEventListener("scroll", this._scrollListener, { passive: true });
115	  }
116	
117	  private _resize(): void {
118	    if (!this._canvas || !this._context) return;
119	    const bounds = this._canvas.getBoundingClientRect();
120	    const width = Math.max(1, Math.round(bounds.width));
121	    const height = Math.max(1, Math.round(bounds.height));
122	    const dpr = Math.min(
123	      ResponsiveRuntime.getDefault().getSnapshot().render.clampedPixelRatio,
124	      SUBPAGE_STARFIELD.pixelRatioMax,
125	    );
126	    this._width = width;
127	    this._height = height;
128	    this._centerX = width * 0.5;
129	    this._centerY = height * 0.5;
130	    this._canvas.width = Math.round(width * dpr);
131	    this._canvas.height = Math.round(height * dpr);
132	    this._context.setTransform(dpr, 0, 0, dpr, 0, 0);
133	  }
134	
135	  private _syncScrollBoost(): void {
136	    const nextY = window.scrollY ?? window.pageYOffset ?? 0;
137	    const delta = Math.abs(nextY - this._lastScrollY);
138	    this._lastScrollY = nextY;
139	    const normalizedBoost = Math.min(
140	      (delta / this._cachedViewportHeight) * SUBPAGE_STARFIELD.scrollBoostFactor,
141	      SUBPAGE_STARFIELD.scrollBoostMax,
142	    );
143	    this._targetScrollBoost = Math.max(this._targetScrollBoost, normalizedBoost);
144	  }
145	
146	  private _seedStars(): void {
147	    this._stars = Array.from(
148	      { length: SUBPAGE_STARFIELD.starCount },
149	      () => this._createStar(),
150	    );
151	  }
152	
153	  private _startLoop(): void {
154	    const render = (): void => {
155	      this._render();
156	      this._rafId = FrameScheduler.request(render);
157	    };
158	    render();
159	  }
160	
161	  private _render(): void {
162	    if (this._resizeDirty) {
163	      this._resizeDirty = false;
164	      this._resize();
165	    }
166	    if (!this._context || this._width <= 0 || this._height <= 0) {
167	      return;
168	    }
169	    const now = performance.now();
170	    const delta = Math.min((now - this._lastFrameTime) / 1000, 1 / 24);
171	    this._lastFrameTime = now;
172	    this._targetScrollBoost = Math.max(
173	      0,
174	      this._targetScrollBoost - delta * SUBPAGE_STARFIELD.scrollBoostDecayPerSecond,
175	    );
176	    const lerpFactor = Math.min(
177	      1,
178	      delta * SUBPAGE_STARFIELD.scrollBoostLerpPerSecond,
179	    );
180	    this._scrollBoost +=
181	      (this._targetScrollBoost - this._scrollBoost) * lerpFactor;
182	
183	    const context = this._context;
184	    // prefers-reduced-motion: 별 이동 정지 (정적 점 표시)
185	    const speed = this._cachedReducedMotion
186	      ? 0
187	      : SUBPAGE_STARFIELD.speed + this._scrollBoost;
188	    context.fillStyle = `rgba(0, 0, 0, ${SUBPAGE_STARFIELD.clearAlpha})`;
189	    context.fillRect(0, 0, this._width, this._height);
190	
191	    for (const star of this._stars) {
192	      star.z -= speed;
193	      if (star.z <= 0) {
194	        this._resetStar(star);
195	      }
196	
197	      const screenX = (star.x / star.z) * this._width + this._centerX;
198	      const screenY = (star.y / star.z) * this._height + this._centerY;
199	      const previousX = (star.x / star.previousZ) * this._width + this._centerX;
200	      const previousY = (star.y / star.previousZ) * this._height + this._centerY;
201	      const brightness = Math.max(
202	        0,
203	        Math.min(
204	          255,
205	          Math.floor((1 - star.z / (this._width * SUBPAGE_STARFIELD.depthRangeFactor)) * 255),
206	        ),
207	      );
208	      const radius = Math.max(
209	        SUBPAGE_STARFIELD.radiusMin,
210	        (1 - star.z / (this._width * SUBPAGE_STARFIELD.depthRangeFactor)) *
211	          SUBPAGE_STARFIELD.radiusMax,
212	      );
213	
214	      context.beginPath();
215	      context.moveTo(previousX, previousY);
216	      context.lineTo(screenX, screenY);
217	      context.strokeStyle = `rgba(${brightness}, ${brightness}, ${brightness}, 1)`;
218	      context.lineWidth = radius;
219	      context.stroke();
220	
221	      star.previousZ = star.z;
222	    }
223	  }
224	
225	  private _createStar(): SubpageStarfieldStar {
226	    return this._resetStar({
227	      x: 0,
228	      y: 0,
229	      z: 0,
230	      previousZ: 0,
231	    });
232	  }
233	
234	  private _resetStar(star: SubpageStarfieldStar): SubpageStarfieldStar {
235	    star.x = (Math.random() - 0.5) * this._width;
236	    star.y = (Math.random() - 0.5) * this._height;
237	    star.z = Math.random() * (this._width * SUBPAGE_STARFIELD.depthRangeFactor);
238	    star.previousZ = star.z;
239	    return star;
240	  }
241	}
