295	  private _normalizeBloomOptions(
296	    bloomOpt: PostProcessorOptions["bloom"],
297	  ): Required<Omit<BloomOptions, "selective">> & { selective: boolean } {
298	    if (typeof bloomOpt !== "object" || bloomOpt == null) {
