301	    const strength = this._clampFinite(
302	      bloomOpt.strength,
303	      DEFAULT_BLOOM.strength,
304	      0,
305	      5,
306	    );
307	    const radius = this._clampFinite(
308	      bloomOpt.radius,
309	      DEFAULT_BLOOM.radius,
310	      0,
311	      2,
312	    );
313	    const threshold = this._clampFinite(
314	      bloomOpt.threshold,
315	      DEFAULT_BLOOM.threshold,
316	      0,
317	      2,
318	    );
319	    const compositeStrength = this._clampFinite(
320	      bloomOpt.compositeStrength,
321	      DEFAULT_BLOOM.compositeStrength,
322	      0,
323	      1,
324	    );
325	    const selective =
326	      typeof bloomOpt.selective === "boolean"
