395	    );
396	    const depthOffMeshes = this._cachedNonBloomMeshes.filter((m) => {
397	      const mat = m.material;
398	      return Array.isArray(mat)
399	        ? mat.every((x) => x.depthTest === false)
400	        : (mat as THREE.Material).depthTest === false;
401	    });
