403	      sceneMeshes: this._cachedSceneMeshes.length,
404	      nonBloomMeshes: this._cachedNonBloomMeshes.length,
405	      depthOffCount: depthOffMeshes.length,
406	      depthOff: depthOffMeshes.map((m) => ({
407	        name: m.name || `(uuid:${m.uuid.slice(0, 8)})`,
408	        renderOrder: m.renderOrder,
409	        materialType: Array.isArray(m.material) ? "multi" : m.material.type,
410	      })),
411	    });
412	  }
